import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CeZVUxyP.js";const g=JSON.parse('{"title":"Languages and libraries for AI-assisted game work","description":"","frontmatter":{},"headers":[],"relativePath":"research/ai-stack.md","filePath":"research/ai-stack.md","lastUpdated":1794255559000}'),n={name:"research/ai-stack.md"};function i(s,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="languages-and-libraries-for-ai-assisted-game-work" tabindex="-1">Languages and libraries for AI-assisted game work <a class="header-anchor" href="#languages-and-libraries-for-ai-assisted-game-work" aria-label="Permalink to &quot;Languages and libraries for AI-assisted game work&quot;">​</a></h1><p><strong>Reviewed: 2026-11-09.</strong> This is a capability map, not a popularity ranking or an AI coding benchmark.</p><h2 id="choose-by-job" tabindex="-1">Choose by job <a class="header-anchor" href="#choose-by-job" aria-label="Permalink to &quot;Choose by job&quot;">​</a></h2><p>AI can write code for an application, operate it through tools, or run as part of the finished application. Those three roles need different libraries. An engine API or geometry library is not itself an AI model.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Languages and libraries</th><th>Why investigate it</th></tr></thead><tbody><tr><td>Asset automation</td><td>Python, <a href="https://docs.blender.org/api/current/" target="_blank" rel="noreferrer">Blender bpy</a>, <a href="https://cadquery.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">CadQuery</a>, <a href="https://trimesh.org/" target="_blank" rel="noreferrer">Trimesh</a></td><td>Generate editable geometry, batch-process assets, and inspect meshes.</td></tr><tr><td>Model experimentation</td><td>Python, <a href="https://pytorch.org/" target="_blank" rel="noreferrer">PyTorch</a>, <a href="https://huggingface.co/docs/transformers/index" target="_blank" rel="noreferrer">Transformers</a></td><td>Evaluate local models when hardware and model support fit the experiment. Not required just to ask a coding assistant for a script.</td></tr><tr><td>Model deployment</td><td><a href="https://onnxruntime.ai/docs/" target="_blank" rel="noreferrer">ONNX Runtime</a> with Python, C++, C#, or JavaScript interfaces</td><td>Test supported model inference outside the original training stack. Conversion and operator compatibility need validation.</td></tr><tr><td>Browser prototype</td><td>JavaScript/TypeScript and <a href="https://threejs.org/docs/" target="_blank" rel="noreferrer">Three.js</a></td><td>A shareable asset viewer and small interactive tests. Rendering is one part of a full game runtime.</td></tr><tr><td>Godot gameplay</td><td><a href="https://docs.godotengine.org/en/stable/getting_started/step_by_step/scripting_languages.html" target="_blank" rel="noreferrer">GDScript, C#, and C/C++ through GDExtension</a></td><td>Compare short iteration loops and integration effort on our vertical slice.</td></tr><tr><td>Unity gameplay</td><td><a href="https://docs.unity.com/en-us/engine/6000.7/manual/scripting/get-started/creating-scripts" target="_blank" rel="noreferrer">C# scripts and Unity APIs</a></td><td>Candidate if its editor and asset ecosystem fit our project.</td></tr><tr><td>Unreal tooling</td><td><a href="https://dev.epicgames.com/documentation/unreal-engine/scripting-the-unreal-editor-using-python?lang=en-US" target="_blank" rel="noreferrer">Editor Python</a></td><td>Useful for editor automation; this Python environment is not packaged-game gameplay scripting.</td></tr><tr><td>CAD automation</td><td><a href="https://aps.autodesk.com/developer/overview/autocad-api" target="_blank" rel="noreferrer">AutoLISP, ObjectARX, and platform-dependent AutoCAD APIs</a></td><td>Research only against the installed product&#39;s supported interfaces.</td></tr><tr><td>Agent integration</td><td><a href="https://modelcontextprotocol.io/docs/learn/architecture" target="_blank" rel="noreferrer">Model Context Protocol</a></td><td>Connect agents to exposed tools and resources. MCP is an integration protocol, not a game engine or an intelligence model.</td></tr><tr><td>Reconstruction reference</td><td><a href="https://github.com/tuunanet/rea-ski-or-die-reconstruction" target="_blank" rel="noreferrer">Rust + SDL2 in the Ski or Die community project</a></td><td>A concrete reported example of implementing behavior recovered through REA. Not evidence that Rust is best for our game.</td></tr></tbody></table><h2 id="proposed-initial-stack" tabindex="-1">Proposed initial stack <a class="header-anchor" href="#proposed-initial-stack" aria-label="Permalink to &quot;Proposed initial stack&quot;">​</a></h2><p>Use <strong>Python for asset scripts and measurements</strong>, <strong>TypeScript for small browser viewers</strong>, and <strong>one engine&#39;s native gameplay language</strong> for the playable slice. Keep model-provider details behind a small interface if we later add runtime inference.</p><p>Avoid training a model or installing a large agent framework until an experiment requires it. First establish whether a direct script and explicit tests solve the task.</p><h2 id="what-to-measure-in-ai-coding-trials" tabindex="-1">What to measure in AI coding trials <a class="header-anchor" href="#what-to-measure-in-ai-coding-trials" aria-label="Permalink to &quot;What to measure in AI coding trials&quot;">​</a></h2><p>Ask for the same door interaction, save/reset behavior, and one bug repair. Measure first-pass correctness, time to a working build, hallucinated APIs, regression rate, human intervention, and ease of a requested change.</p><p>Record model/version, engine/library version, documentation supplied, tools available, and attempt count. Differences in editor access and API documentation can dominate the result; do not attribute every failure to the programming language.</p><h2 id="two-kinds-of-game-ai" tabindex="-1">Two kinds of game AI <a class="header-anchor" href="#two-kinds-of-game-ai" aria-label="Permalink to &quot;Two kinds of game AI&quot;">​</a></h2><p><strong>Development-time AI</strong> helps build assets and code. <strong>Runtime AI</strong> executes while someone plays. The latter adds latency, reliability, cost, and reproducibility requirements. We should establish a working conventional game loop before testing runtime model features.</p>',13)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
